import sys
import heapq

def main():
    import sys
    import heapq

    def read_ints():
        return list(map(int, sys.stdin.readline().split()))

    n, c = read_ints()
    a = read_ints()

    def calculate_value(subarray):
        if len(subarray) == 0:
            return 0
        k = len(subarray)
        exclude_count = k // c
        if exclude_count == 0:
            return sum(subarray)
        heap = []
        for num in subarray:
            heapq.heappush(heap, num)
            if len(heap) > exclude_count:
                heapq.heappop(heap)
        return sum(subarray) - sum(heap)

    min_sum = float('inf')
    current_subarray = []
    current_sum = 0

    for num in a:
        current_subarray.append(num)
        current_sum += num
        if len(current_subarray) >= c:
            value = calculate_value(current_subarray)
            min_sum = min(min_sum, current_sum - value)
            current_subarray.pop(0)
            current_sum -= a[0]

    print(min_sum)

if __name__ == "__main__":
    main()
